  const loadGame = async () => {
    if (!user) return;
    try {
      const snapshot = await getDocs(collection(db, 'artifacts', appId, 'users', user.uid, 'saves'));
      if (!snapshot.empty) {
        const data = snapshot.docs[0].data();
        if (data.grid) setGrid(typeof data.grid === 'string' ? JSON.parse(data.grid) : data.grid);
        if (data.resources) {
            setResources(data.resources);
            if (data.resources.turn > MAX_TURNS) setIsGameOver(true);
        }
        showNotification("存档已读取！");
      } else {
        showNotification("未找到存档");
      }
    } catch (e) {
      console.error(e);
      showNotification("读取失败");
    }
  };

  const submitScore = async (finalValues) => {
    if (!user) return;
    const currentRes = finalValues || resources;
