    const finalScore = Math.max(0, score);

    try {
      const recordId = `${user.uid}_${Date.now()}`;
      const scoreData = {
        name: playerName || "匿名市长",
        score: finalScore,
        population: currentRes.population,
        happiness: currentRes.happiness,
        pollution: currentRes.pollution,
        uid: user.uid,
        timestamp: new Date().toISOString()
      };
      await setDoc(doc(db, 'artifacts', appId, 'public', 'data', 'leaderboard', recordId), scoreData);
      showNotification("分数已上传！");
      fetchLeaderboard();
      setShowLeaderboard(true);
    } catch (e) {
      console.error(e);
    }
  };

  // --- Dynamic Sky Styles ---
  const getSkyStyle = () => {
    switch (dayPhase) {
      case 'day': return 'bg-slate-900';
      case 'sunset': return 'bg-slate-950 transition-colors duration-[1200ms]';
      case 'night': return 'bg-black transition-colors duration-[1000ms]';
      case 'sunrise': return 'bg-slate-900 transition-colors duration-[1200ms]';
      default: return 'bg-slate-900';
    }
  };

  return (
    <div className={`flex flex-col h-screen ${getSkyStyle()} text-slate-100 font-sans overflow-hidden transition-colors duration-1000`}>

      {/* Top Bar - High Z-Index */}
      <div className="bg-slate-800 border-b border-slate-700 p-4 flex justify-between items-center shadow-lg z-50 relative">
        <div className="flex items-center gap-6">
          <h1 className="text-xl font-bold bg-gradient-to-r from-blue-400 to-cyan-400 bg-clip-text text-transparent">
            未来城市规划局
          </h1>
          <div className="flex gap-4 text-sm font-mono">
            <StatItem 
              icon={Coins} 
              value={`$${resources.budget}`} 
              color="text-yellow-400" 
              label="资金" 
              tooltip="收入=税收-绿地维护($50/个)。商业区远离道路收益骤减(-80%)。评分权重: 0.1"
            />
            <StatItem 
              icon={Users} 
              value={resources.population} 
              color="text-blue-300" 
              label="人口" 
              tooltip="增长需高幸福度。居住区远离道路(>2格)增长变慢。评分权重: 10"
            />
            <StatItem 
              icon={Smile} 
              value={resources.happiness} 
              color="text-green-400" 
              label="幸福总值" 
              tooltip="全城居民幸福度总和。结算规则: >人口加分, <人口扣分。评分权重: 动态"
            />
            <StatItem 
              icon={Factory} 
              value={resources.pollution} 
              color="text-gray-400" 
              label="污染度" 
              tooltip="工厂每回合固定+5。每回合自然净化 6 点。评分权重: -10 (扣分)"
            />
          </div>
        </div>

        <div className="flex gap-2">
           <input 
             type="text" 
