import { LucideIcon } from 'lucide-react';

export type BuildingTypeID = 'EMPTY' | 'RESIDENTIAL' | 'COMMERCIAL' | 'INDUSTRIAL' | 'PARK' | 'ROAD' | 'OCEAN' | 'DEMOLISH';

