export const createInitialGrid = (): CellData[][] => {
  const grid: CellData[][] = [];
  for (let y = 0; y < GRID_SIZE; y++) {
    const row: CellData[] = [];
    for (let x = 0; x < GRID_SIZE; x++) {
      if (x === 0) {
        row.push({ x, y, type: 'ROAD', builtTurn: 0 });
      } else if (x >= GRID_SIZE - OCEAN_COLUMNS) {
        row.push({ x, y, type: 'OCEAN', builtTurn: 0 });
      } else {
        row.push({ x, y, type: 'EMPTY', builtTurn: 0 });
      }
    }
    grid.push(row);
  }
  return grid;
};

export const calculateRoadDistances = (grid: CellData[][]): number[][] => {
  const distMap = Array(GRID_SIZE).fill(0).map(() => Array(GRID_SIZE).fill(Infinity));
  const queue: {x: number, y: number, d: number}[] = [];

  for (let y = 0; y < GRID_SIZE; y++) {
    for (let x = 0; x < GRID_SIZE; x++) {
      if (grid[y][x].type === 'ROAD') {
        distMap[y][x] = 0;
        queue.push({x, y, d: 0});
      }
    }
  }

  const dirs = [[0,1], [0,-1], [1,0], [-1,0]];

  while (queue.length > 0) {
    const next = queue.shift();
    if (!next) break;
    const {x, y, d} = next;

    for (const [dx, dy] of dirs) {
      const nx = x + dx;
      const ny = y + dy;

      if (nx >= 0 && nx < GRID_SIZE && ny >= 0 && ny < GRID_SIZE) {
        if (distMap[ny][nx] === Infinity) {
          distMap[ny][nx] = d + 1;
          queue.push({x: nx, y: ny, d: d + 1});
        }
      }
    }
  }
  return distMap;
};

import React, { useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
import { Particle } from '../types';

export interface ParticleHandle {
  spawn: (x: number, y: number, type: Particle['type'], text?: string) => void;
  spawnIncome: (x: number, y: number, amount: number) => void;
}

const ParticleOverlay = forwardRef<ParticleHandle, {}>((props, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const particlesRef = useRef<Particle[]>([]);
  const frameIdRef = useRef<number>(0);

  useImperativeHandle(ref, () => ({
    spawn: (x: number, y: number, type: 'dust' | 'sparkle' | 'smoke', text?: string) => {
      const count = type === 'dust' ? 8 : type === 'smoke' ? 3 : 5;
      for (let i = 0; i < count; i++) {
        particlesRef.current.push({
          id: Math.random(),
          x,
          y,
          vx: (Math.random() - 0.5) * 4,
          vy: (Math.random() - 0.5) * 4 - (type === 'smoke' ? 2 : 0),
          life: 1.0,
          maxLife: 1.0,
          color: type === 'dust' ? '#cbd5e1' : type === 'smoke' ? '#475569' : '#fbbf24',
          size: Math.random() * 4 + 2,
          type
        });
      }
    },
    spawnIncome: (x: number, y: number, amount: number) => {
      particlesRef.current.push({
        id: Math.random(),
        x,
        y: y - 20, // Start slightly above
        vx: 0,
        vy: -1.5, // Float up
        life: 1.0,
        maxLife: 1.5, // Longer life
        color: amount > 0 ? '#4ade80' : '#f87171',
        size: 14,
        type: 'text',
        text: amount > 0 ? `+$${amount}` : `-$${Math.abs(amount)}`
      });
    }
  }));

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const render = () => {
      if (!canvas) return;
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      particlesRef.current.forEach((p, index) => {
        p.x += p.vx;
        p.y += p.vy;
        p.life -= 0.02;

        if (p.type === 'smoke') {
            p.size += 0.1; 
        }

        ctx.globalAlpha = Math.max(0, p.life);

        if (p.type === 'text' && p.text) {
          ctx.font = `bold ${p.size}px monospace`;
          ctx.fillStyle = p.color;
          ctx.fillText(p.text, p.x, p.y);
          // Add a simple stroke for readability
          ctx.strokeStyle = 'rgba(0,0,0,0.5)';
          ctx.lineWidth = 2;
          ctx.strokeText(p.text, p.x, p.y);
        } else {
          ctx.fillStyle = p.color;
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
          ctx.fill();
        }
      });

      // Remove dead particles
      particlesRef.current = particlesRef.current.filter(p => p.life > 0);
      ctx.globalAlpha = 1.0;

      frameIdRef.current = requestAnimationFrame(render);
    };

    // Resize handler
    const handleResize = () => {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
    };
    window.addEventListener('resize', handleResize);
    handleResize(); // Init

    render();

    return () => {
      cancelAnimationFrame(frameIdRef.current);
      window.removeEventListener('resize', handleResize);
    };
  }, []);

  return (
    <canvas 
      ref={canvasRef} 
      className="absolute inset-0 pointer-events-none z-[80]"
    />
  );
});

export default ParticleOverlay;

import React from 'react';
import { BuildingTypeID } from '../types';
import { BUILDING_TYPES } from '../utils';
import { TreePine, Waves } from 'lucide-react';

