import React from 'react';
import { BuildingTypeID } from '../types';
import { BUILDING_TYPES } from '../utils';
import { TreePine, Waves } from 'lucide-react';

interface Props {
  type: BuildingTypeID;
  connect: { top: boolean; bottom: boolean; left: boolean; right: boolean };
  age: number;
  dayPhase: string;
}

const BuildingBlock = React.memo(({ type, connect, age, dayPhase }: Props) => {
  const info = BUILDING_TYPES[type];
  const height = info.heightClass || 'h-8';

  // Animation for construction (scale up)
  const isNew = age === 0;
  const animationClass = isNew ? 'animate-in zoom-in duration-500' : '';

  const style = { backgroundColor: info.color, transformStyle: 'preserve-3d' as const };

  const getFaceStyle = () => {
     // Window pattern for residential/commercial
     if (type === 'RESIDENTIAL' || type === 'COMMERCIAL') {
        return {
           backgroundImage: `
            linear-gradient(rgba(255,255,255,0.1) 1px, transparent 1px), 
            linear-gradient(90deg, rgba(255,255,255,0.1) 1px, transparent 1px)
           `,
           backgroundSize: '8px 12px',
        };
     }
     if (type === 'INDUSTRIAL') {
        return {
           backgroundImage: 'repeating-linear-gradient(45deg, transparent, transparent 5px, rgba(0,0,0,0.2) 5px, rgba(0,0,0,0.2) 10px)',
        };
     }
     return {};
  };

  const faceStyle = getFaceStyle();

  // Helper for window lights during night
  const WindowLight = () => (
    <div className={`absolute w-[4px] h-[6px] bg-yellow-200 shadow-[0_0_4px_2px_rgba(253,224,71,0.6)] transition-opacity duration-1000`} 
         style={{ opacity: 'var(--window-opacity)' }} />
  );

  return (
    <div className={`absolute inset-1 pointer-events-none ${animationClass}`} style={{ transformStyle: 'preserve-3d' }}>

      {/* Side Faces - Adjusted for standard X-rotation perspective */}
      {/* South Face (Front) */}
      {!connect.bottom && <div className={`absolute bottom-0 left-0 right-0 ${height} brightness-[0.7]`} style={{ ...style, ...faceStyle, transformOrigin: 'bottom', transform: 'rotateX(-90deg)' }} />}

      {/* West Face (Left) */}
      {!connect.left && (
        <div className={`absolute left-0 bottom-0 top-0 ${height} brightness-[0.8] overflow-hidden`} style={{ ...style, ...faceStyle, width: '100%', transformOrigin: 'left', transform: 'rotateY(90deg)' }}>
           {(type === 'RESIDENTIAL' || type === 'COMMERCIAL') && (
             <div className="w-full h-full flex flex-wrap gap-1 p-1 content-start justify-center">
                <WindowLight /> <WindowLight /> <WindowLight />
                <div className="w-full" /> 
                <WindowLight /> <WindowLight />
             </div>
           )}
        </div>
      )}

      {/* East Face (Right) */}
      {!connect.right && (
        <div className={`absolute right-0 bottom-0 top-0 ${height} brightness-[0.6] overflow-hidden`} style={{ ...style, ...faceStyle, width: '100%', transformOrigin: 'right', transform: 'rotateY(90deg)' }}>
             {(type === 'RESIDENTIAL' || type === 'COMMERCIAL') && (
             <div className="w-full h-full flex flex-wrap gap-1 p-1 content-start justify-center">
                <WindowLight /> <WindowLight />
                <div className="w-full" /> 
                <WindowLight /> <WindowLight /> <WindowLight />
             </div>
           )}
        </div>
      )}

      {/* North Face (Back) */}
      {!connect.top && <div className={`absolute top-0 left-0 right-0 ${height} brightness-[0.9]`} style={{ ...style, ...faceStyle, transformOrigin: 'top', transform: 'rotateX(-90deg)' }} />}

      {/* Top Face */}
      <div className={`absolute inset-0 ${height ? `translate-z-${height}` : ''} flex items-center justify-center transition-all duration-1000`} 
           style={{ 
             ...style, 
             // Adjusted Z-translations for non-isometric view
             transform: type === 'COMMERCIAL' ? 'translateZ(16px)' : type === 'INDUSTRIAL' ? 'translateZ(24px)' : type === 'RESIDENTIAL' ? 'translateZ(20px)' : 'translateZ(4px)',
             border: '1px solid rgba(255,255,255,0.2)',
             boxShadow: 'inset 0 0 10px rgba(0,0,0,0.1)'
           }}>

         {type === 'RESIDENTIAL' && (
           <div className="w-full h-full bg-amber-200/20 border-4 border-amber-300/30 flex items-center justify-center">
              <div className="w-2/3 h-2/3 bg-orange-400/20 rounded-sm" />
           </div>
         )}

         {type === 'COMMERCIAL' && (
           <div className="w-full h-full relative overflow-hidden bg-white/10">
              <div className="absolute top-1 left-1 right-1 h-1 bg-blue-500/50" />
              <div className="absolute bottom-1 left-1 right-1 h-1 bg-blue-500/50" />
              {/* HVAC Unit */}
             <div className="absolute top-1 right-1 w-3 h-3 bg-gray-400 border border-gray-500 shadow-sm rounded-sm" />
           </div>
         )}

         {type === 'PARK' && (
             <div className="w-full h-full flex items-center justify-center bg-emerald-500/50 overflow-hidden relative">
               <div className="absolute inset-0 bg-emerald-600/30 rounded-full scale-75 blur-sm" />
               <TreePine size={24} className="text-emerald-900 absolute -top-4 drop-shadow-lg" style={{ transform: 'rotateX(-45deg)' }} />
               {/* Small pond */}
               <div className="absolute bottom-0 right-0 w-4 h-4 bg-cyan-400/60 rounded-tl-lg" />
             </div>
         )}

         {type === 'INDUSTRIAL' && (
           <div className="w-full h-full flex items-center justify-center bg-gray-700 border-2 border-yellow-600/50 relative overflow-hidden">
             {/* Smoke Stacks */}
             <div className="w-3 h-3 bg-black rounded-full shadow-inner absolute top-1 left-1">
                {[0, 1].map((i) => (
                  <div key={i} className="absolute top-0 left-0 w-full h-full bg-gray-400 rounded-full opacity-0 animate-ping"
                    style={{ animationDuration: '2s', animationDelay: `${i}s` }} />
                ))}
             </div>
             <div className="w-2 h-2 bg-black rounded-full shadow-inner absolute bottom-2 right-2" />
           </div>
         )}
      </div>
    </div>
  );
}, (prev, next) => {
  return prev.type === next.type && 
         prev.age === next.age &&
         prev.dayPhase === next.dayPhase &&
         prev.connect.top === next.connect.top &&
         prev.connect.bottom === next.connect.bottom &&
         prev.connect.left === next.connect.left &&
         prev.connect.right === next.connect.right;
});

export default BuildingBlock;

import React, { useMemo } from 'react';
import { CellData, BuildingTypeID, DayPhase } from '../types';
import { BUILDING_TYPES, GRID_SIZE } from '../utils';
import BuildingBlock from './BuildingBlock';
import { Waves } from 'lucide-react';

interface Props {
  cell: CellData;
  grid: CellData[][];
  currentTurn: number;
  dayPhase: DayPhase;
  onClick: (e: React.MouseEvent) => void;
}

const GridCell = React.memo(({ cell, grid, currentTurn, dayPhase, onClick }: Props) => {
  const { x, y, type } = cell;

  const nTop = y > 0 ? grid[y - 1][x] : null;
  const nBottom = y < GRID_SIZE - 1 ? grid[y + 1][x] : null;
  const nLeft = x > 0 ? grid[y][x - 1] : null;
  const nRight = x < GRID_SIZE - 1 ? grid[y][x + 1] : null;

  const connect = useMemo(() => ({
    top: nTop && nTop.type === type,
    bottom: nBottom && nBottom.type === type,
    left: nLeft && nLeft.type === type,
    right: nRight && nRight.type === type
  }), [nTop, nBottom, nLeft, nRight, type]);

  const isOcean = type === 'OCEAN';
  const isEmpty = type === 'EMPTY';
  const isRoad = type === 'ROAD';
  const age = currentTurn - (cell.builtTurn || 0);

  return (
    <div 
      onClick={onClick}
      className="relative w-12 h-12 cursor-pointer group hover:z-20"
      style={{ transformStyle: 'preserve-3d' }}
    >
      {/* Base Plane */}
      <div 
        className={`absolute inset-0 border border-white/5 transition-colors duration-500
          ${isOcean ? 'bg-cyan-900/80' : isEmpty ? 'bg-slate-800 hover:bg-slate-700' : 'bg-slate-800'}`} 
      />

      {/* Hover Selection Highlight */}
      <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity duration-200 border-2 border-white/30" />

      {!isEmpty && !isOcean && !isRoad && (
        <BuildingBlock type={type} connect={connect} age={age} dayPhase={dayPhase} />
      )}

      {isRoad && (
         <div className="absolute inset-0 flex items-center justify-center pointer-events-none" style={{ transform: 'translateZ(1px)' }}>
            <div className="w-6 h-6 bg-slate-500 z-10 rounded-sm" /> 
            {connect.top && <div className="absolute top-0 w-6 h-[calc(50%+1px)] bg-slate-500" />}
            {connect.bottom && <div className="absolute bottom-0 w-6 h-[calc(50%+1px)] bg-slate-500" />}
            {connect.left && <div className="absolute left-0 h-6 w-[calc(50%+1px)] bg-slate-500" />}
            {connect.right && <div className="absolute right-0 h-6 w-[calc(50%+1px)] bg-slate-500" />}
            {/* Road Markings */}
            <div className="w-1.5 h-1.5 bg-yellow-400/50 rounded-full z-20" />
         </div>
      )}

      {isOcean && (
         <div className="absolute inset-0 bg-cyan-500/40 backdrop-blur-[1px] overflow-hidden">
            <Waves size={16} className="text-cyan-200 opacity-60 absolute top-2 left-2 animate-pulse" />
            <div className="absolute inset-0 bg-gradient-to-br from-transparent to-cyan-900/50" />
         </div>
      )}
    </div>
  );
}, (prev, next) => {
  if (prev.cell !== next.cell) return false; 
  if (prev.dayPhase !== next.dayPhase) return false;

  const getType = (g: CellData[][], x: number, y: number) => (y >= 0 && y < 15 && x >= 0 && x < 15) ? g[y][x].type : null;
  const px = prev.cell.x; const py = prev.cell.y;
  const dirs = [[0,-1], [0,1], [-1,0], [1,0]];
  for (let [dx, dy] of dirs) {
    if (getType(prev.grid, px + dx, py + dy) !== getType(next.grid, px + dx, py + dy)) return false;
  }
  return true; 
});

export default GridCell;

