export const createInitialGrid = (): CellData[][] => {
  const grid: CellData[][] = [];
  for (let y = 0; y < GRID_SIZE; y++) {
    const row: CellData[] = [];
    for (let x = 0; x < GRID_SIZE; x++) {
      if (x === 0) {
        row.push({ x, y, type: 'ROAD', builtTurn: 0 });
      } else if (x >= GRID_SIZE - OCEAN_COLUMNS) {
        row.push({ x, y, type: 'OCEAN', builtTurn: 0 });
      } else {
        row.push({ x, y, type: 'EMPTY', builtTurn: 0 });
      }
    }
    grid.push(row);
  }
  return grid;
};

export const calculateRoadDistances = (grid: CellData[][]): number[][] => {
  const distMap = Array(GRID_SIZE).fill(0).map(() => Array(GRID_SIZE).fill(Infinity));
  const queue: {x: number, y: number, d: number}[] = [];

  for (let y = 0; y < GRID_SIZE; y++) {
    for (let x = 0; x < GRID_SIZE; x++) {
      if (grid[y][x].type === 'ROAD') {
        distMap[y][x] = 0;
        queue.push({x, y, d: 0});
      }
    }
  }

  const dirs = [[0,1], [0,-1], [1,0], [-1,0]];

  while (queue.length > 0) {
    const next = queue.shift();
    if (!next) break;
    const {x, y, d} = next;

    for (const [dx, dy] of dirs) {
      const nx = x + dx;
      const ny = y + dy;

      if (nx >= 0 && nx < GRID_SIZE && ny >= 0 && ny < GRID_SIZE) {
        if (distMap[ny][nx] === Infinity) {
          distMap[ny][nx] = d + 1;
          queue.push({x: nx, y: ny, d: d + 1});
        }
      }
    }
  }
  return distMap;
};

