import React, { useMemo } from 'react';
import { CellData, BuildingTypeID, DayPhase } from '../types';
import { BUILDING_TYPES, GRID_SIZE } from '../utils';
import BuildingBlock from './BuildingBlock';
import { Waves } from 'lucide-react';

interface Props {
  cell: CellData;
  grid: CellData[][];
  currentTurn: number;
  dayPhase: DayPhase;
  onClick: (e: React.MouseEvent) => void;
}

const GridCell = React.memo(({ cell, grid, currentTurn, dayPhase, onClick }: Props) => {
  const { x, y, type } = cell;

  const nTop = y > 0 ? grid[y - 1][x] : null;
  const nBottom = y < GRID_SIZE - 1 ? grid[y + 1][x] : null;
  const nLeft = x > 0 ? grid[y][x - 1] : null;
  const nRight = x < GRID_SIZE - 1 ? grid[y][x + 1] : null;

  const connect = useMemo(() => ({
    top: nTop && nTop.type === type,
    bottom: nBottom && nBottom.type === type,
    left: nLeft && nLeft.type === type,
    right: nRight && nRight.type === type
  }), [nTop, nBottom, nLeft, nRight, type]);

  const isOcean = type === 'OCEAN';
  const isEmpty = type === 'EMPTY';
  const isRoad = type === 'ROAD';
  const age = currentTurn - (cell.builtTurn || 0);

  return (
    <div 
      onClick={onClick}
      className="relative w-12 h-12 cursor-pointer group"
      style={{ transformStyle: 'preserve-3d' }}
    >
      {/* Base Plane - The Clickable Floor */}
      <div 
        className={`absolute inset-0 border border-white/5 transition-colors duration-500
          ${isOcean ? 'bg-cyan-900/80' : isEmpty ? 'bg-slate-800 hover:bg-slate-700' : 'bg-slate-800'}`} 
      />

      {/* Hover Effect - Uses translateZ to float slightly above floor */}
      <div className="absolute inset-0 bg-white/20 opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity duration-150 border-2 border-white/50 z-20" 
           style={{ transform: 'translateZ(1px)' }} />

      {!isEmpty && !isOcean && !isRoad && (
        <BuildingBlock type={type} connect={connect} age={age} dayPhase={dayPhase} />
      )}

      {isRoad && (
         <div className="absolute inset-0 flex items-center justify-center pointer-events-none" style={{ transform: 'translateZ(1px)' }}>
            {/* Main Road Surface */}
            <div className="absolute inset-0 bg-slate-600 rounded-sm" />

            {/* Lane Connections (Darker asphalt) */}
            {connect.top && <div className="absolute top-0 w-6 h-[55%] bg-slate-600" />}
            {connect.bottom && <div className="absolute bottom-0 w-6 h-[55%] bg-slate-600" />}
            {connect.left && <div className="absolute left-0 h-6 w-[55%] bg-slate-600" />}
            {connect.right && <div className="absolute right-0 h-6 w-[55%] bg-slate-600" />}

            {/* White Dashed Markings */}
            <div className="relative w-full h-full flex items-center justify-center">
               {/* Center Hub */}
               <div className="w-1.5 h-1.5 bg-white/50 rounded-full z-10" />

               {/* Dashes */}
               {connect.top && <div className="absolute top-0 w-0.5 h-[50%] border-l-2 border-dashed border-white/60" />}
               {connect.bottom && <div className="absolute bottom-0 w-0.5 h-[50%] border-l-2 border-dashed border-white/60" />}
               {connect.left && <div className="absolute left-0 h-0.5 w-[50%] border-t-2 border-dashed border-white/60" />}
               {connect.right && <div className="absolute right-0 h-0.5 w-[50%] border-t-2 border-dashed border-white/60" />}
            </div>
         </div>
      )}

      {isOcean && (
         <div className="absolute inset-0 bg-cyan-500/40 backdrop-blur-[1px] overflow-hidden">
            <Waves size={16} className="text-cyan-200 opacity-60 absolute top-2 left-2 animate-pulse" />
            <div className="absolute inset-0 bg-gradient-to-br from-transparent to-cyan-900/50" />
         </div>
      )}
    </div>
  );
});

