        <div className="flex-1 relative overflow-hidden flex justify-center items-center bg-radial-gradient"> 

          {/* Sky Elements */}
          <div className="absolute inset-0 pointer-events-none">
             <div className={`absolute right-24 transition-all duration-[1500ms] ease-in-out z-0
