                    key={`${x}-${y}`} 
                    cell={cell} 
                    grid={grid} 
                    currentTurn={resources.turn} 
                    dayPhase={dayPhase}
                    dragPreview={dragPreview.has(`${x},${y}`) ? selectedTool : undefined}
                    onMouseDown={(e) => handleMouseDown(x, y, e)}
