          {notification && (
            <div className="absolute top-8 left-1/2 -translate-x-1/2 bg-blue-500/90 backdrop-blur text-white px-8 py-3 rounded-full shadow-[0_0_20px_rgba(59,130,246,0.5)] animate-bounce z-[70] font-bold tracking-wide">
              {notification}
