          {showLeaderboard && (
            <div className="absolute inset-0 bg-black/80 z-[80] flex items-center justify-center backdrop-blur-sm animate-in fade-in duration-200">
              <div className="bg-slate-900 border border-slate-700 p-8 rounded-2xl w-[32rem] max-h-[80vh] flex flex-col shadow-2xl relative overflow-hidden">
